import os
import random

import numpy as np
import torch

INPUT_PATH = "input/"
FEATURE_PATH = "feature/"
MODEL_PATH = "model/"
SUB_PATH = "sub/"


def seed_everything(seed=42):
    """Set random seeds for reproducible results across different libraries"""
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False
    os.environ["PYTHONHASHSEED"] = str(seed)

    try:
        import torch_geometric

        torch_geometric.seed_everything(seed)
    except ImportError:
        pass

    print(f"Random seed set to {seed} for reproducible results")


# ===== src/data/smiles_data.py =====

import math

from rdkit import Chem
import torch
from torch.utils.data import Dataset


class SMILESTokenizer:
    """Character-level SMILES tokenizer based on unique characters in dataset"""

    def __init__(self):
        self.special_tokens = {"<PAD>": 0, "<UNK>": 1, "<START>": 2, "<END>": 3}
        self.char_to_idx = self.special_tokens.copy()
        self.idx_to_char = {v: k for k, v in self.special_tokens.items()}

    def tokenize(self, smiles):
        """Tokenize SMILES string into characters"""
        return list(smiles)

    @staticmethod
    def _coerce_smiles(smiles):
        """Map missing / non-string values to '' so encode() never crashes.

        Graph featurization already returns a dummy graph for non-strings (NaN,
        None, pd.NA). Sequence scoring must do the same: DataRobot's custom
        model test injects nulls, and ``Series.tolist()`` turns them into
        ``float('nan')``, which ``list(nan)`` raises TypeError on.
        """
        return smiles if isinstance(smiles, str) else ""

    def fit(self, smiles_list):
        """Build vocabulary from unique characters in SMILES strings"""
        unique_chars = set()
        valid_count = 0
        for smi in smiles_list:
            if not isinstance(smi, str):
                continue
            try:
                mol = Chem.MolFromSmiles(smi)
            except Exception:
                continue
            if mol is None:
                continue
            unique_chars.update(set(smi))
            valid_count += 1

        print(f"Found {len(unique_chars)} unique characters in {valid_count} valid SMILES")
        print(f"Unique characters: {sorted(unique_chars)}")

        # Continue past whatever is already mapped rather than restarting at
        # len(special_tokens): re-fitting the same instance would otherwise
        # hand an id that is already taken to the first new character, so two
        # characters would share one embedding row.
        idx = max(self.char_to_idx.values()) + 1 if self.char_to_idx else 0
        for char in sorted(unique_chars):
            if char not in self.char_to_idx:
                self.char_to_idx[char] = idx
                self.idx_to_char[idx] = char
                idx += 1

        print(f"Vocabulary size: {len(self.char_to_idx)}")
        return self

    def encode(self, smiles, max_length=None):
        """Convert SMILES to character indices"""
        smiles = self._coerce_smiles(smiles)
        chars = self.tokenize(smiles)
        indices = [self.special_tokens["<START>"]]
        for char in chars:
            if char in self.char_to_idx:
                indices.append(self.char_to_idx[char])
            else:
                indices.append(self.special_tokens["<UNK>"])
        indices.append(self.special_tokens["<END>"])

        if max_length:
            if len(indices) > max_length:
                indices = indices[: max_length - 1] + [self.special_tokens["<END>"]]
            else:
                indices.extend([self.special_tokens["<PAD>"]] * (max_length - len(indices)))
        return indices

    def decode(self, indices):
        """Convert character indices back to SMILES"""
        chars = []
        for idx in indices:
            if idx in self.idx_to_char:
                char = self.idx_to_char[idx]
                if char not in ["<PAD>", "<START>", "<END>", "<UNK>"]:
                    chars.append(char)
        return "".join(chars)


class SMILESDataset(Dataset):
    """Dataset for SMILES sequences"""

    def __init__(self, smiles_list, targets=None, tokenizer=None, max_length=200):
        self.smiles_list = smiles_list
        self.targets = targets
        self.tokenizer = tokenizer
        self.max_length = max_length
        # Reject unusable labels up front. A blank Tc cell arrives as NaN,
        # which torch happily wraps in a tensor; the first batch containing it
        # NaNs every weight and the run only fails later, inside sklearn, with
        # no hint that one empty cell caused it.
        if targets is not None:
            for i, t in enumerate(targets):
                try:
                    t_float = float(t)
                except (TypeError, ValueError):
                    raise ValueError(f"Target at row {i} is not numeric: {t!r}")
                if not math.isfinite(t_float):
                    raise ValueError(f"Target at row {i} is not finite: {t!r}")
        # START + SMILES + END must fit in max_length; anything longer is
        # silently truncated by encode() and can drop chemically important
        # tails (e.g. a polymer attachment point). Warn once at construction.
        n_trunc = 0
        longest = 0
        for s in smiles_list:
            n = len(s) if isinstance(s, str) else 0
            if n > longest:
                longest = n
            if n + 2 > max_length:
                n_trunc += 1
        if n_trunc:
            print(
                f"WARNING: {n_trunc} SMILES exceed max_length={max_length} "
                f"(longest string is {longest} chars, needs {longest + 2} "
                f"tokens with <START>/<END>) and will be truncated"
            )

    def __len__(self):
        return len(self.smiles_list)

    def __getitem__(self, idx):
        smiles = self.smiles_list[idx]
        encoded = self.tokenizer.encode(smiles, self.max_length)
        encoded_tensor = torch.tensor(encoded, dtype=torch.long)
        if self.targets is not None:
            target = torch.tensor([float(self.targets[idx])], dtype=torch.float)
            return encoded_tensor, target
        else:
            return encoded_tensor


# ===== src/data/graph_features.py =====

import math

from rdkit import Chem
import torch
from torch_geometric.data import Data

# Width of the per-bond feature vector built in smiles_to_graph. Needed to shape
# an empty edge_attr for molecules that have no bonds at all (a single atom, e.g.
# "C" or "[Na+]"), where the bond loop never runs and there is no sample vector
# to measure. Keep in step with the `bond_feat` list below.
BOND_FEATURE_DIM = 21

# Shortest-path distances are >= 0. The previous sentinel (10.0) collided with a
# real 10-bond path, so "no * in this fragment" looked identical to "ten bonds
# from *". Negative is reserved for missing.
NO_ATTACHMENT_PATH = -1.0


def is_carbonyl_carbon(atom, mol):
    """Carbonyl carbon: C=O"""
    if atom.GetAtomicNum() != 6:
        return False
    for neighbor in atom.GetNeighbors():
        if neighbor.GetAtomicNum() == 8:
            bond = mol.GetBondBetweenAtoms(atom.GetIdx(), neighbor.GetIdx())
            if bond.GetBondType() == Chem.rdchem.BondType.DOUBLE:
                return True
    return False


def is_carboxyl_carbon(atom, mol):
    """Carboxyl carbon: C(=O)OH"""
    if not is_carbonyl_carbon(atom, mol):
        return False
    oh_count = 0
    for neighbor in atom.GetNeighbors():
        # MolFromSmiles leaves hydrogens implicit, so looking for an explicit
        # H *atom* among the oxygen's neighbours never matches. Ask the
        # oxygen how many hydrogens it carries instead.
        if neighbor.GetAtomicNum() == 8 and neighbor.GetTotalNumHs(includeNeighbors=True) > 0:
            oh_count += 1
    return oh_count > 0


def _get_attachment_distance(atom, mol):
    """Shortest-path distance to the nearest attachment point (`*`).

    Returns 0.0 when this atom *is* an attachment point, and
    ``NO_ATTACHMENT_PATH`` (-1) when there is no `*` or no path to one
    (a disconnected fragment in a '.'-separated SMILES).
    """
    try:
        if atom.GetAtomicNum() == 0:
            return 0.0

        attachment_atoms = [a for a in mol.GetAtoms() if a.GetAtomicNum() == 0]
        if not attachment_atoms:
            return NO_ATTACHMENT_PATH

        min_distance = float("inf")
        for attachment in attachment_atoms:
            try:
                distance = Chem.rdmolops.GetShortestPath(mol, atom.GetIdx(), attachment.GetIdx())
                # GetShortestPath returns an EMPTY tuple (not None) when the two
                # atoms live in disconnected fragments. Treat empty / degenerate
                # paths as "no path" so the -1 sentinel applies.
                if distance:
                    path_length = len(distance) - 1
                    if 0 <= path_length < min_distance:
                        min_distance = path_length
            except Exception:
                try:
                    visited = set()
                    queue = [(atom.GetIdx(), 0)]
                    visited.add(atom.GetIdx())
                    while queue:
                        current_idx, dist = queue.pop(0)
                        if current_idx == attachment.GetIdx():
                            if dist < min_distance:
                                min_distance = dist
                            break
                        current_atom = mol.GetAtomWithIdx(current_idx)
                        for neighbor in current_atom.GetNeighbors():
                            neighbor_idx = neighbor.GetIdx()
                            if neighbor_idx not in visited:
                                visited.add(neighbor_idx)
                                queue.append((neighbor_idx, dist + 1))
                except Exception:
                    continue

        return float(min_distance) if min_distance != float("inf") else NO_ATTACHMENT_PATH
    except Exception:
        return NO_ATTACHMENT_PATH


def _is_potential_crosslink_bond(atom1, atom2, mol):
    """Check if this bond could be involved in polymer crosslinking"""
    try:
        aromatic_bond = atom1.GetIsAromatic() or atom2.GetIsAromatic()
        high_degree = atom1.GetTotalDegree() > 3 or atom2.GetTotalDegree() > 3
        heteroatom_bond = atom1.GetAtomicNum() not in [1, 6] or atom2.GetAtomicNum() not in [1, 6]
        return int(aromatic_bond or high_degree or heteroatom_bond)
    except:
        return 0


def _has_attachment_neighbor(atom, mol):
    """Check if atom has an attachment point (*) as a neighbor"""
    try:
        for neighbor in atom.GetNeighbors():
            if neighbor.GetAtomicNum() == 0:
                return True
        return False
    except:
        return False


def smiles_to_graph(smiles_str, atom_map, y_val=None):
    """
    Converts a SMILES string into a PyTorch Geometric Data object.
    Returns a zero-filled graph if the SMILES cannot be featurized.

    An unusable *target*, by contrast, raises: a bad label is a data error,
    not a molecule to be tolerated. Fabricating 0.0 for an unparseable value
    (e.g. a censored ``<0.05``) hides it inside the real Tc range, and
    letting NaN through NaNs every weight on the first batch and only
    surfaces much later as a sklearn "Input contains NaN" error.
    """
    y_float = None
    if y_val is not None:
        try:
            y_float = float(y_val)
        except (TypeError, ValueError):
            raise ValueError(f"Target for SMILES {smiles_str!r} is not numeric: {y_val!r}")
        if not math.isfinite(y_float):
            raise ValueError(f"Target for SMILES {smiles_str!r} is not finite: {y_val!r}")

    def create_zero_graph():
        x = torch.zeros((1, len(atom_map) + 12), dtype=torch.float)
        edge_index = torch.empty((2, 0), dtype=torch.long)
        edge_attr = torch.empty((0, BOND_FEATURE_DIM), dtype=torch.float)
        if y_float is not None:
            y_tensor = torch.tensor([[y_float]], dtype=torch.float)
            return Data(
                x=x, edge_index=edge_index, edge_attr=edge_attr, y=y_tensor, smiles=str(smiles_str)
            )
        else:
            return Data(x=x, edge_index=edge_index, edge_attr=edge_attr, smiles=str(smiles_str))

    try:
        if not isinstance(smiles_str, str) or not smiles_str.strip():
            return create_zero_graph()
        if not isinstance(atom_map, dict) or not atom_map:
            return create_zero_graph()

        mol = Chem.MolFromSmiles(smiles_str)
        if mol is None or mol.GetNumAtoms() == 0:
            return create_zero_graph()

        # Node Features
        node_features = []
        for atom in mol.GetAtoms():
            try:
                symbol = atom.GetSymbol()
                features = [0] * len(atom_map)
                if symbol in atom_map:
                    features[atom_map[symbol]] = 1
                features.extend(
                    [
                        atom.GetAtomicNum(),
                        atom.GetTotalDegree(),
                        atom.GetFormalCharge(),
                        atom.GetTotalNumHs(includeNeighbors=True),
                        atom.GetNumRadicalElectrons(),
                        int(atom.GetIsAromatic()),
                        int(atom.IsInRing()),
                        int(atom.GetHybridization() == Chem.rdchem.HybridizationType.SP),
                        int(atom.GetHybridization() == Chem.rdchem.HybridizationType.SP2),
                        int(atom.GetHybridization() == Chem.rdchem.HybridizationType.SP3),
                        int(atom.GetHybridization() == Chem.rdchem.HybridizationType.S),
                        int(atom.GetHybridization() == Chem.rdchem.HybridizationType.UNSPECIFIED),
                    ]
                )
                node_features.append(features)
            except:
                return create_zero_graph()

        if not node_features:
            return create_zero_graph()

        try:
            x = torch.tensor(node_features, dtype=torch.float)
        except:
            return create_zero_graph()

        # Edge Index and Features
        edge_indices, edge_attrs = [], []
        try:
            for bond in mol.GetBonds():
                i, j = bond.GetBeginAtomIdx(), bond.GetEndAtomIdx()
                if i >= mol.GetNumAtoms() or j >= mol.GetNumAtoms():
                    continue
                edge_indices.extend([(i, j), (j, i)])
                bt = bond.GetBondType()
                stereo = bond.GetStereo()
                atom1 = bond.GetBeginAtom()
                atom2 = bond.GetEndAtom()
                angles_1 = len([n for n in atom1.GetNeighbors() if n.GetIdx() != atom2.GetIdx()])
                angles_2 = len([n for n in atom2.GetNeighbors() if n.GetIdx() != atom1.GetIdx()])
                dist_1 = float(_get_attachment_distance(atom1, mol))
                dist_2 = float(_get_attachment_distance(atom2, mol))

                # Direction-independent part of the bond vector.
                shared_head = [
                    int(bt == Chem.rdchem.BondType.SINGLE),
                    int(bt == Chem.rdchem.BondType.DOUBLE),
                    int(bt == Chem.rdchem.BondType.TRIPLE),
                    int(bt == Chem.rdchem.BondType.AROMATIC),
                    int(bt == Chem.rdchem.BondType.DATIVE),
                    int(stereo == Chem.rdchem.BondStereo.STEREONONE),
                    int(stereo == Chem.rdchem.BondStereo.STEREOZ),
                    int(stereo == Chem.rdchem.BondStereo.STEREOE),
                    int(stereo == Chem.rdchem.BondStereo.STEREOCIS),
                    int(stereo == Chem.rdchem.BondStereo.STEREOTRANS),
                    int(stereo == Chem.rdchem.BondStereo.STEREOANY),
                    int(bond.IsInRing()),
                    int(bond.GetIsConjugated()),
                ]
                shared_mid = [
                    float(min(angles_1, angles_2)),
                    float(max(angles_1, angles_2)),
                ]
                shared_tail = [
                    int(_is_potential_crosslink_bond(atom1, atom2, mol)),
                    int(
                        _has_attachment_neighbor(atom1, mol) or _has_attachment_neighbor(atom2, mol)
                    ),
                ]

                # The four per-atom slots are keyed to RDKit's begin/end
                # assignment, which follows the order the atoms appear in the
                # input string. Emitting the same vector for both directed
                # copies therefore made slot meaning depend on how the SMILES
                # happened to be written, and left the model unable to tell
                # whether a slot describes the edge's source or destination.
                # Order them source-first per direction instead.
                edge_attrs.extend(
                    [
                        shared_head
                        + [float(angles_1), float(angles_2)]
                        + shared_mid
                        + [dist_1, dist_2]
                        + shared_tail,
                        shared_head
                        + [float(angles_2), float(angles_1)]
                        + shared_mid
                        + [dist_2, dist_1]
                        + shared_tail,
                    ]
                )
        except:
            edge_indices, edge_attrs = [], []

        try:
            if edge_indices:
                edge_index = torch.tensor(edge_indices, dtype=torch.long).t().contiguous()
                edge_attr = torch.tensor(edge_attrs, dtype=torch.float)
            else:
                edge_index = torch.empty((2, 0), dtype=torch.long)
                edge_attr = torch.empty((0, BOND_FEATURE_DIM), dtype=torch.float)
        except:
            return create_zero_graph()

        try:
            if y_float is not None:
                y_tensor = torch.tensor([[y_float]], dtype=torch.float)
                return Data(
                    x=x, edge_index=edge_index, edge_attr=edge_attr, y=y_tensor, smiles=smiles_str
                )
            else:
                return Data(x=x, edge_index=edge_index, edge_attr=edge_attr, smiles=smiles_str)
        except:
            return create_zero_graph()
    except:
        return create_zero_graph()


# ===== src/data/loader.py =====

import os

import numpy as np
import pandas as pd
from rdkit import Chem

# stripped intra-package import: from .smiles_data import SMILESTokenizer


def _training_smiles(input_path, smiles_col="SMILES"):
    """Collect SMILES from ``train.csv`` only.

    The atom map and tokenizer must not see ``test.csv``: those rows are the
    held-out scoring set. ``valid.csv`` is no longer part of the layout (it was
    merged into train.csv) and is ignored here, matching :func:`load_split`.
    Unseen symbols at score time get an all-zero one-hot / ``<UNK>``.
    """
    path = os.path.join(input_path, "train.csv")
    df = pd.read_csv(path)
    return df[smiles_col].tolist()


def build_atom_map_from_smiles(smiles_iter):
    """Build atom map from any iterable of SMILES strings.

    Used by the notebook pipeline (via ``train.csv``) and by the DRUM
    ``custom.fit`` hook (via the in-memory training frame). Test SMILES never
    contribute atom types.
    """
    atoms_set = set()
    n_invalid = 0
    for s in smiles_iter:
        if not isinstance(s, str):
            n_invalid += 1
            continue
        try:
            mol = Chem.MolFromSmiles(s)
        except Exception:
            n_invalid += 1
            continue
        if mol is None:
            n_invalid += 1
            continue
        for atom in mol.GetAtoms():
            atoms_set.add(atom.GetSymbol())
    if n_invalid:
        # smiles_to_graph turns each of these into the same all-zero one-node
        # graph while keeping its real target, so the model is fit against
        # contradictory labels on an identical input. Say how many.
        print(
            f"WARNING: {n_invalid} SMILES could not be parsed by RDKit and will "
            f"featurize as empty graphs"
        )
    return {atom: idx for idx, atom in enumerate(sorted(atoms_set))}


def build_tokenizer_from_smiles(smiles_iter):
    """Fit a SMILESTokenizer on any iterable of SMILES strings."""
    print("Fitting tokenizer...")
    tokenizer = SMILESTokenizer()
    tokenizer.fit(list(smiles_iter))
    return tokenizer


def _smiles_col(cfg):
    return cfg.get("data", {}).get("smiles_column", "SMILES")


def load_split(cfg):
    """Load the train and test CSVs.

    There is no separate ``valid.csv`` any more - the old validation rows were
    merged into ``train.csv``. Carve a validation set out of the training frame
    with :func:`split_train_valid`.

    Returns:
        (train_df, test_df)
    """
    input_path = cfg["paths"]["input"]

    train_df = pd.read_csv(os.path.join(input_path, "train.csv"))
    test_df = pd.read_csv(os.path.join(input_path, "test.csv"))

    print(f"Loaded data from {input_path}:")
    print(f"  train: {len(train_df)}, test: {len(test_df)}")

    return train_df, test_df


def load_or_split(cfg):
    """Backwards-compatible alias for :func:`load_split`."""
    return load_split(cfg)


def split_train_valid(train_df, cfg, valid_ratio=None):
    """Randomly carve a validation set out of ``train_df``.

    Default ratio comes from ``cfg['data']['valid_ratio']`` (0.2 -> a 4:1
    train/valid split). The split is seeded with ``cfg['seed']`` so stage 1 of
    the notebook is reproducible.

    Returns:
        (sub_train_df, valid_df)
    """
    if valid_ratio is None:
        valid_ratio = cfg.get("data", {}).get("valid_ratio", 0.2)

    rng = np.random.RandomState(cfg.get("seed", 42))
    idx = rng.permutation(len(train_df))
    n_valid = int(round(len(train_df) * valid_ratio))

    valid_idx = idx[:n_valid]
    train_idx = idx[n_valid:]

    sub_train_df = train_df.iloc[train_idx].reset_index(drop=True)
    valid_df = train_df.iloc[valid_idx].reset_index(drop=True)

    print(
        f"Split train.csv {1 - valid_ratio:.0%}/{valid_ratio:.0%}: "
        f"train {len(sub_train_df)}, valid {len(valid_df)}"
    )

    return sub_train_df, valid_df


def build_atom_map(cfg):
    """Build atom map for GNN pipeline (honours data.smiles_column)."""
    return build_atom_map_from_smiles(_training_smiles(cfg["paths"]["input"], _smiles_col(cfg)))


def build_tokenizer(cfg):
    """Build and fit tokenizer for sequence pipeline (honours data.smiles_column)."""
    return build_tokenizer_from_smiles(_training_smiles(cfg["paths"]["input"], _smiles_col(cfg)))


# ===== src/models/_scatter.py =====

"""`scatter_add` without a hard dependency on ``torch_scatter``.

``torch_scatter`` ships compiled C++/CUDA extensions whose wheel must match the
exact torch build (and CUDA toolkit) of the environment. When it doesn't, the
import fails *at load time* of the shared object, e.g. on DataRobot Notebooks::

    OSError: Could not load this library:
        .../site-packages/torch_scatter/_scatter_cuda.so

That is an ``OSError``, not an ``ImportError``, so both have to be caught.

Fallbacks, in order:
1. ``torch_scatter.scatter_add`` — used when it imports cleanly.
2. ``torch_geometric.utils.scatter(..., reduce="sum")`` — PyG >= 2.3, numerically
   identical to (1).
3. A pure-torch ``Tensor.scatter_add_`` implementation — no extra deps at all.
"""
import torch


def _scatter_add_torch(src, index, dim=0, dim_size=None):
    """Pure-torch equivalent of ``torch_scatter.scatter_add``."""
    if dim < 0:
        dim = src.dim() + dim
    if dim_size is None:
        dim_size = int(index.max()) + 1 if index.numel() > 0 else 0

    size = list(src.shape)
    size[dim] = dim_size
    out = torch.zeros(size, dtype=src.dtype, device=src.device)

    view_shape = [1] * src.dim()
    view_shape[dim] = -1
    idx = index.view(view_shape).expand_as(src)
    return out.scatter_add_(dim, idx, src)


try:
    from torch_scatter import scatter_add  # noqa: F401 - fast path when usable
except (ImportError, OSError):  # broken/mismatched C++ extension counts as OSError
    try:
        from torch_geometric.utils import scatter as _pyg_scatter

        def scatter_add(src, index, dim=0, dim_size=None):
            return _pyg_scatter(src, index, dim=dim, dim_size=dim_size, reduce="sum")

    except ImportError:
        scatter_add = _scatter_add_torch

